#include <stddef.h>
#include <stdlib.h>
int trace(void){int a[4]={1,3,5,7};int total=0;for(int i=0;i<4;i++)total+=a[i];return total;}

#include <stddef.h>
#include <stdlib.h>
struct N{int v;struct N*next;};int trace(void){struct N c={3,NULL},b={2,&c},a={1,&b};int count=0;for(struct N*p=&a;p!=NULL;p=p->next)count++;return count;}

#include <stddef.h>
#include <stdlib.h>
struct N{struct N*l,*r;};int count(struct N*p){return p==NULL?0:1+count(p->l)+count(p->r);}int trace(void){struct N a={NULL,NULL},b={NULL,NULL},root={&a,&b};return count(&root);}

